package com.quancrypt.qbank.payment.infrastructure.config;

import java.nio.file.Path;
import org.springframework.boot.context.properties.ConfigurationProperties;

/**
 * Service settings. {@code certsDir} is the directory with the PEM files generated by reference-system/certs;
 * {@code accountServiceUrl} is the base URL of the account service; the MQTT settings describe the broker
 * subscription (D-98, D-103).
 */
@ConfigurationProperties("qbank")
public record QbankProperties(String certsDir, String accountServiceUrl, AccountClient accountClient, Mqtt mqtt) {

    /** Timeouts of calls to the account service, in milliseconds. */
    public record AccountClient(int connectTimeoutMs, int readTimeoutMs) {
    }

    /** MQTT broker connection and subscription. */
    public record Mqtt(String brokerUrl, String clientId, String topicFilter, int qos, int retrySeconds) {

        public Mqtt {
            if (brokerUrl == null || !brokerUrl.startsWith("ssl://")) {
                throw new IllegalArgumentException("qbank.mqtt.broker-url must start with ssl://");
            }
        }
    }

    /** Fails at startup when a URL would send the caller's token or the JWKS request over a plain connection. */
    public QbankProperties {
        if (accountServiceUrl == null || !accountServiceUrl.startsWith("https://")) {
            throw new IllegalArgumentException("qbank.account-service-url must start with https://");
        }
    }

    public Path certsPath() {
        return Path.of(certsDir);
    }
}
